// Run "npm run sync-format" in studio/ to update it from the app.
// Grade-dependent features, in one place so the app works for any grade from KG1
// (grade -1) to 12. Thresholds are by grade, never by a particular school or child.
// No imports: the golden fingerprint follows this file (task 136), and the bundle format
// takes its grade range from here (task 146).

/** The youngest grade there is: KG1, which the bundle format numbers -1. */
export const GRADE_MIN = -1;

/** The last school year the app covers. */
export const GRADE_MAX = 12;

/**
 * From this grade, children see "I think that's wrong" under Mr. Zaki's replies. Younger
 * children tend to tap it to dodge a question, so it starts in upper primary.
 */
export const RECHECK_MIN_GRADE = 4;

/** The grade as a person writes it in English: "KG1", "KG2", "Grade 7". */
export function gradeName(grade: number): string {
	if (grade === GRADE_MIN) return "KG1";
	if (grade === 0) return "KG2";
	return `Grade ${grade}`;
}

/**
 * The grade for a prompt or a writer, with the age the model needs: "KG1 (about 4 years
 * old)", "KG2 (about 5 years old)", and "Grade 7" as before from Grade 1 up.
 */
export function gradeForPrompt(grade: number): string {
	if (grade === GRADE_MIN) return "KG1 (about 4 years old)";
	if (grade === 0) return "KG2 (about 5 years old)";
	return `Grade ${grade}`;
}

/** A grade moved up or down, never past KG1 or Grade 12 (e.g. "four grades lower"). */
export function shiftGrade(grade: number, by: number): number {
	return Math.min(GRADE_MAX, Math.max(GRADE_MIN, grade + by));
}
